<p class="eyebrow">Secure checkout</p><h1>Place your order</h1><?php if ($error): ?><div class="store-error" role="alert"><?= e($error) ?></div><?php endif; ?>
<?php if (!$methods): ?><div class="store-error"><strong>Checkout is not ready yet.</strong> The business needs to enable at least one payment method.</div><?php else: ?><form method="post" class="checkout-layout"><?= $csrf->field() ?><input type="hidden" name="checkout_nonce" value="<?= e_attr($checkoutNonce) ?>"><section class="panel checkout-form"><h2>Contact information</h2><div class="field-grid"><label>Full name<input name="name" required maxlength="190" autocomplete="name" value="<?= e_attr($input['name'] ?? '') ?>"></label><label>Email address<input type="email" name="email" required maxlength="190" autocomplete="email" value="<?= e_attr($input['email'] ?? '') ?>"></label></div><label>Phone number<input name="phone" maxlength="60" autocomplete="tel" value="<?= e_attr($input['phone'] ?? '') ?>"></label><h2>Fulfillment</h2><?php foreach ($fulfillment as $method): ?><label class="choice"><input type="radio" name="fulfillment" value="<?= e_attr($method) ?>" required <?= ($input['fulfillment'] ?? '')===$method?'checked':'' ?>><span><strong><?= e(ucfirst($method)) ?></strong><small>The business will confirm timing and any applicable charges.</small></span></label><?php endforeach; ?><div class="field-grid"><label>Address<input name="address_line1" maxlength="190" autocomplete="address-line1" value="<?= e_attr($input['address_line1'] ?? '') ?>"></label><label>Address line 2<input name="address_line2" maxlength="190" autocomplete="address-line2" value="<?= e_attr($input['address_line2'] ?? '') ?>"></label><label>City<input name="city" maxlength="120" autocomplete="address-level2" value="<?= e_attr($input['city'] ?? '') ?>"></label><label>State / region<input name="region" maxlength="120" autocomplete="address-level1" value="<?= e_attr($input['region'] ?? '') ?>"></label></div><label>Postal code<input name="postal_code" maxlength="30" autocomplete="postal-code" value="<?= e_attr($input['postal_code'] ?? '') ?>"></label><h2>Manual payment method</h2><?php foreach ($methods as $key=>$method): ?><label class="choice"><input type="radio" name="payment_method" value="<?= e_attr($key) ?>" required <?= ($input['payment_method'] ?? '')===$key?'checked':'' ?>><span><strong><?= e($method['label']) ?></strong><small><?= e($method['instructions'] ?: 'Payment instructions will be confirmed with your order.') ?></small></span></label><?php endforeach; ?><label>Order notes<textarea name="notes" rows="4" maxlength="2000"><?= e($input['notes'] ?? '') ?></textarea></label></section><aside class="panel summary"><h2>Order total</h2><?php foreach($cart['items'] as $line): ?><div class="summary-row"><span><?= (int)$line['quantity'] ?> × <?= e($line['product']['name']) ?></span><strong>$<?= number_format((int)$line['line_total_minor']/100,2) ?></strong></div><?php endforeach; ?><div class="summary-row summary-total"><strong>Total</strong><strong><?= e($cart['currency']) ?> $<?= number_format((int)$cart['subtotal']/100,2) ?></strong></div><p class="muted">Your payment remains pending until the business confirms receipt.</p><button class="btn" type="submit">Place order</button></aside></form><?php endif; ?>
